style.css:
@-moz-document domain("scp-wiki.wikidot.com"), domain("scpwiki.com"), domain("scp-wiki.net"), domain("scp-wiki.wdfiles.com") {
/* ============================================================
     BASE
     ============================================================ */

  /* Headings and links state a colour directly on the element, so they cannot
     reach an author's callout box by inheritance the way body ink does. They
     read these instead, and a light author box rebinds them for its subtree. */
  :root {
    color-scheme: dark;
    --scp-title: #e05f6b;
    --scp-heading: #e6edf3;
    --scp-link: #e8626e;
    --scp-link-visited: #cf90a8;
    --scp-link-hover: #ff8f97;
    --scp-lift-black: #c4cdd6;
    --scp-lift-blue: #79c0ff;
    --scp-lift-green: #7ee787;
    --scp-lift-purple: #d2a8ff;
    --scp-lift-maroon: #ff9492;
    --scp-lift-red: #ff453a;
    --scp-lift-brown: #d4a373;
    --scp-lift-teal: #56d4dd;
  }

  /* Black Highlighter declares its whole palette on :root and feeds the site
     CHROME from it — the sidebar, the page-options button row, the Site tools
     flyout, modals, hover-blocks, the footnote footer and the editor menus all
     read these. The article body is remapped separately on #page-content, which
     never reaches any of them.
     Only tokens that exclusively mean "a surface" or "body ink" are remapped.
     --swatch-background and --white-monochrome stay light on purpose: BH also
     uses them as knocked-out text ON its crimson fills (the history page's
     first column, the tag editor, form focus rows), and a dark value there is
     unreadable on the crimson. */
  :root {
    --swatch-text-general: 196, 205, 214;
    --swatch-text-tertiary-color: 196, 205, 214;
    --swatch-menutxt-general-color: 196, 205, 214;
    --swatch-menubg-color: 20, 24, 29;
    --swatch-secondary-color: 34, 40, 47;
    --swatch-border-color: 45, 51, 59;
    --rating-module-bg-color: 26, 31, 38;
    --pager-text: 196, 205, 214;

    /* Themes derived from Black Highlighter (a large share of post-2020
       articles ship one) name these two directly on :root instead of letting
       them fall out of --swatch-secondary-color, which bypasses the remap
       above. They are the page-options button row. Sigma-9 never reads them,
       so its bare-text bar is untouched. */
    --ui-button-bg: 34, 40, 47;
    --ui-button-txt: 196, 205, 214;

    /* Black Highlighter's "black end" swatch, and the fill behind both halves
       of its sidebar drawer scrim — #main-content::before on desktop and
       .close-menu on mobile, each at 30%. The themes that swap the monochromes
       (penumbra and everything derived from it) resolve it near-white, so
       opening the drawer washes the whole article light grey instead of dimming
       it. Neither scrim exists until the drawer is open, so no load-time scan
       reaches them. Sigma-9 never reads this token. */
    --swatch-menubg-black-color: 5, 7, 10;

    /* Middle stop of --gradient-topmenu-mobile (the phone-width top-bar band)
       and of --gradient-topmenu (the desktop one, which #container-wrap covers).
       Black Highlighter reads it nowhere else, so recolouring it darkens the
       band without touching any other surface. */
    --swatch-topmenu-bg-color: 28, 33, 40;
  }

  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  div#container-wrap,
  div#container-wrap-wrap,
  #container,
  #content-wrap,
  #main-content,
  #page-content,
  #skrollr-body,
  #html-body {
    background-color: transparent;
  }

  /* The masthead art is already dark on both skins, so only the paper under it
     is stated. The image is deliberately NOT restated: naming Sigma-9's own
     body_bg.svg here paints it onto Black Highlighter pages too, where it lands
     as a stray block because the article theme's background-size and -repeat
     still apply to it. */
  div#container-wrap {
    background-color: #14181d !important;
  }

  /* iframes default to a 2px inset border in currentColor, which turns light
     the moment the page text does. */
  iframe {
    border-color: #2d333b;
  }

  /* ============================================================
     TYPOGRAPHY
     ============================================================ */

  #page-title,
  h1,
  .meta-title {
    color: var(--scp-title) !important;
  }

  /* Sigma-9 draws the title's rule in #bbb. The pin stops at the title element:
     an h1 framed in an accent inside the article body is stating the page's own
     identity (the Site News red bars), not drawing chrome. */
  #page-title,
  .meta-title {
    border-color: #2d333b !important;
  }

  /* No border-color here on purpose. Guide pages rule off their section
     headings with a border that names no colour, so currentColor carries the
     ink stated above and the separator keeps the weight it has natively;
     pinning it to a chrome grey collapses it to nothing. */
  h2,
  h3,
  h4,
  h5,
  h6 {
    color: var(--scp-heading);
  }

  /* Declared on the article root ONLY, so the ink reaches the text by
     inheritance. A copy of this on p/li/dd/dt/td is a direct declaration and
     beats any colour an author put on a wrapping callout box, however specific
     or inline that wrapper's colour was — which erases the author's ink while
     leaving their light paper behind. */
  #page-content,
  .thread-container .post .content,
  .forum-thread-box .description-block {
    color: #c4cdd6;
  }

  /* Black Highlighter — the modern site theme, used by most post-2020 articles
     — paints article surfaces from this token layer. Remapping the tokens
     instead of the components covers every widget they feed (content tables,
     the author card behind the byline, callouts) including the ones that only
     exist on hover. Scoped to the article body: the header, sidebar and top
     menu are painted by their own rules and must not follow. */
  #page-content {
    --swatch-background: 26, 31, 38;
    --swatch-text-general: 196, 205, 214;
    --swatch-border-color: 45, 51, 59;
    --tables-body-bg: 26, 31, 38;
    --tables-body-txt: 196, 205, 214;
    --tables-border: 45, 51, 59;
    --tables-header-bg: 34, 40, 47;
    --tables-header-txt: 230, 237, 243;
  }

  /* Authors build callout boxes as [[div style="background:#f2f2c2"]] and let
     the site's near-black body ink carry the words — the wrapper names a paper
     colour and no ink. That paper survives the theme, so the box has to hand
     the ink back. Matched on the VALUE (an inline background alongside a light
     hex or `white`), never on a class: the classes are page-local and differ
     per article.
     Deliberately NOT !important — an author who did name their own colour
     still wins, so this can never read worse than the unstyled site.
     A dark box carrying a pale border hex matches too. That is survivable and
     deliberately not filtered: such a box has to name its own light ink to
     work on the site's white page, that inline ink beats everything here, and
     the boxes seen doing it hold no text of their own. Filtering it needs a
     `color:`-bearing :not(), which also drops the light boxes that DO name
     their ink — and those still need the rebinds below for their headings and
     links. */
  #page-content [style*="background"][style*="#c"],
  #page-content [style*="background"][style*="#d"],
  #page-content [style*="background"][style*="#e"],
  #page-content [style*="background"][style*="#f"],
  #page-content [style*="background"][style*="#C"],
  #page-content [style*="background"][style*="#D"],
  #page-content [style*="background"][style*="#E"],
  #page-content [style*="background"][style*="#F"],
  #page-content [style*="background"][style*="white"] {
    color: #1b1815;
    --scp-title: #7a1d24;
    --scp-heading: #1b1815;
    --scp-link: #a4161a;
    --scp-link-visited: #6d3550;
    --scp-link-hover: #d21414;
    /* Black Highlighter's own light values are the right ones on paper, so the
       remap above is handed back for anything the box contains — an ACS bar or
       a content table nested in a callout follows the paper, not the page. */
    --swatch-background: 252, 252, 252;
    --swatch-text-general: 27, 24, 21;
    --swatch-border-color: 160, 160, 160;
    --tables-body-bg: 252, 252, 252;
    --tables-body-txt: 27, 24, 21;
    --tables-border: 160, 160, 160;
    /* Same for the ##blue|…## inline palette: on paper the author's own dark
       end reads, and the lifted end does not. */
    --scp-lift-black: #1b1815;
    --scp-lift-blue: #0000cd;
    --scp-lift-green: #046307;
    --scp-lift-purple: #800080;
    --scp-lift-maroon: #800000;
    --scp-lift-red: #c30000;
    --scp-lift-brown: #6b4423;
    --scp-lift-teal: #006a6a;
  }

  hr {
    color: #2d333b !important;
    background-color: #2d333b !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     LINKS — the crimson identity, lifted for dark
     ============================================================ */

  a,
  #interwiki a,
  #side-bar a,
  #page-content a {
    color: var(--scp-link);
  }

  a:visited,
  #page-content a:visited {
    color: var(--scp-link-visited);
  }

  a:hover,
  #page-content a:hover {
    color: var(--scp-link-hover);
  }

  /* Article themes reach the body links from their own page-scoped rules, which
     out-specify a single-id selector — on the themes that pitch their links
     near-black for a light page, that leaves them invisible here. Two ids win
     on the id count alone, so no !important is needed and an author's inline
     colour (and the ##name|text## lifts further down) still take precedence.
     Every other article-link rule is doubled to the same weight below. */
  #main-content #page-content a {
    color: var(--scp-link);
  }

  #main-content #page-content a:visited {
    color: var(--scp-link-visited);
  }

  #main-content #page-content a:hover {
    color: var(--scp-link-hover);
  }

  /* Wikidot paints a light hover fill on every link. Kept at low specificity
     so component rules (the rating buttons) can still fill their own hover. */
  a:hover {
    background-color: transparent !important;
  }

  a.newpage,
  a.newpage:visited,
  #main-content #page-content a.newpage,
  #main-content #page-content a.newpage:visited {
    color: #e8944a;
  }

  #page-content a.collapsible-block-link {
    color: var(--scp-link);
  }

  /* The author-info rail (a shared component) is drawn by article themes with a
     light pill behind its links, which the crimson ink above cannot sit on. */
  #page-content .info-container a {
    background-color: transparent !important;
  }

  /* The front page colour-codes links by content type (SCP / Tale / GoI /
     Artwork) through --link-color; hand those back after the broad rule. */
  #main-content #page-content a.core-link,
  #page-content .masthead .line.middle {
    color: var(--link-color);
  }

  /* ============================================================
     HEADER / TOP BAR
     ============================================================ */

  #header h1 a {
    color: #eee;
  }

  /* Sigma-9 already paints the tagline #f0f0c0, and Black Highlighter HIDES this
     span with `color: transparent` while drawing its own copy from a ::before —
     so a colour here does not improve Sigma and un-hides a second tagline on
     every Black Highlighter page. Deliberately left unstyled.

     That Black Highlighter copy reads two tokens that mean nothing but "masthead
     ink", and article themes pitch them at their own accent for a light page —
     /scp-1730 lands the whole title at 1.8:1. Rebinding the tokens matches
     Sigma-9's own pair, and a theme whose masthead is knocked-out artwork
     (djkaktus paints its gold through background-clip) is untouched because
     `color` is not what draws it. */
  #header {
    --swatch-headerh1-color: 238, 238, 238;
    --swatch-headerh2-color: 240, 240, 192;
  }

  /* The themes that skip the token and name the pseudo's colour outright: the
     "R&C Site-43" family states #000, which on a dark masthead is nothing at
     all. Sigma-9 gives these pseudos no content, so they have no box there and
     the rule costs nothing; a theme that paints its title as knocked-out
     artwork keeps it, because `color` is not what draws that. The cost is the
     handful of themes whose masthead is already a legible cream or gold — those
     land on the site's own pair instead of their own.
     Only `color` is taken. -webkit-text-fill-color is what a background-clip
     title sets to transparent so its artwork shows through the glyphs, and
     naming it here would paint over that artwork. */
  #header h1 a::before,
  #header h1 a::after {
    color: #eee !important;
  }

  #header h2::before,
  #header h2::after,
  #header h2 span::before,
  #header h2 span::after {
    color: #f0f0c0 !important;
  }

  /* Article themes derived from Black Highlighter repaint the masthead from
     their own palette, so the chrome states its ink rather than relying on the
     cascade order. The site's own skins leave this strip unfilled; the ones that
     do fill it pitch a near-white for their light masthead. */
  #login-status {
    background-color: transparent !important;
    color: #9aa4ae !important;
  }

  #login-status a {
    color: #dde3e9 !important;
  }

  /* "Sign in" carries .btn-primary but renders as bare text on the masthead. */
  #login-status a.btn,
  #login-status a.btn-primary {
    background-color: transparent !important;
    border-color: transparent !important;
    color: #dde3e9 !important;
  }

  #login-status ul a,
  #account-options li a {
    color: #e8626e !important;
  }

  #account-options {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: 0 4px 14px rgba(0, 0, 0, .6);
  }

  #account-options li a:hover {
    color: #ff8f97 !important;
    background-color: #262c33 !important;
  }

  #account-topbutton {
    background-color: #2d333b !important;
    color: #e8626e !important;
    border-color: #3a4048 !important;
  }

  #top-bar a {
    color: #eaeaea !important;
  }

  /* The dropdown panel carries its own fill on Black Highlighter — the anchor
     fills below only cover the rows, not the gaps between them.
     Its elevation shadow is drawn from a token that means "ink", so the remap
     above turns the article themes' accent-tinted halo into a pale one; the
     panel's own rule out-specifies this one, hence the !important. */
  #top-bar ul li ul {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    box-shadow: 0 4px 12px rgba(0, 0, 0, .7) !important;
  }

  #top-bar ul li a {
    border-color: rgba(255, 255, 255, .06);
  }

  /* Open dropdown: the site paints these #eee / #fff */
  #top-bar ul li.sfhover a,
  #top-bar ul li:hover a,
  #top-bar li ul li a,
  #top-bar a:hover {
    background-color: #1c2128 !important;
    color: #ff8f97 !important;
    border-left-color: #3a4048 !important;
    border-right-color: #3a4048 !important;
  }

  #top-bar ul li.sfhover a:hover,
  #top-bar ul li:hover a:hover {
    background-color: #262c33 !important;
  }

  #top-bar ul li.sfhover ul li a,
  #top-bar ul li:hover ul li a {
    border-top-color: #2d333b !important;
  }

  #top-bar ul li ul a {
    color: #ff8f97;
  }

  /* Mobile hamburger. The glyph is the anchor's own "≡" character, and the
     article themes derived from Black Highlighter hold its `color` at a
     near-black pitched for their light bar — no specificity or !important on
     `color` dislodges it (/scp-1730 keeps 15, 15, 15 against a two-id
     !important rule). -webkit-text-fill-color is what actually paints the
     glyph and nothing claims it, so stating it is what makes the bars show. */
  #top-bar .open-menu a {
    background-color: #1c2128 !important;
    border-color: #4a5058 !important;
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }

  #top-bar .open-menu a:hover {
    box-shadow: 0 0 16px 2px rgba(0, 0, 0, .8);
  }

  /* Below the desktop breakpoint the article themes swap the menu for their own
     bar and fill it with a background-IMAGE, so a near-white band runs across
     the top of every phone viewport. The band is --gradient-topmenu-mobile,
     whose middle stop is the token remapped on :root above, so recolouring the
     token darkens the band and leaves its two hairline edges intact.
     Do NOT state a flat fill here instead: Sigma-9 leaves this element
     transparent and sizes it to the menu text only, so a colour paints a slab
     over the masthead art at 390px. The hamburger inside it reads the theme's
     ink, which is pitched for the light band. */
  #top-bar .mobile-top-bar {
    border-color: #3a4048 !important;
  }

  #top-bar .mobile-top-bar a {
    color: #eaeaea !important;
  }

  /* Search button. Black Highlighter clips this input to a magnifier mask and
     paints the GLYPH with the element's own BACKGROUND, so a fill stated here
     becomes the icon's colour, and the skins want opposite values: a masked skin
     needs it LIGHT to read on our bar, while the ones that leave a real "Search"
     button — Sigma-9, and article themes like /scp-8007 that drop its gradient —
     need it DARK under their own near-white label. The .user.css picks the side
     per skin by reading the theme's own token, which userstyles.org's parser
     cannot accept (its rgb() wants three numbers and dies on `var(`, taking the
     whole upload down with a 502). DELIBERATE DIVERGENCE FROM THE .user.css,
     ONE OF TWO IN THIS FILE (the other is the `[name="search"]` exclusion on the
     `input.btn` group further down, which this fill depends on): no selector
     distinguishes the two skin families — the markup is identical and only the
     imported theme CSS differs — so this build states a single mid maroon that
     clears 3:1 both ways (glyph 3.1:1 on the top bar, near-white label 3.2:1 on
     the fill) instead of serving one family and blanking the other. Any value
     stated here must stay a mid tone for that reason. No background-IMAGE is
     stated, so Sigma-9's own opaque brand gradient covers this colour entirely
     and is unaffected. */
  #search-top-box-form input[type="submit"] {
    background-color: #a05a5a !important;
    border-color: #6d4a4a !important;
  }

  /* The base fill above is !important and would otherwise freeze the skin's own
     hover swap on the button skins. Lifted far enough to stay visible against the
     dark red panel Black Highlighter slides in behind the glyph on hover, while
     the label the skins switch to #fff here keeps 3.4:1. */
  #search-top-box-form input[type="submit"]:hover,
  #search-top-box-form input[type="submit"]:focus {
    background-color: #c07878 !important;
    border-color: #b98a8a !important;
  }

  /* The account glyph beside it is the same trap one element over: below the
     desktop breakpoint Black Highlighter masks #login-status::before to a
     person icon and paints it from --login-mobile-icon-color, which the
     themes pitch near-black for their light bar (/scp-1730 states
     15, 15, 15). Unlike the search button there is no opposite case to serve —
     the mask lives in the shared Black Highlighter sheet, so every skin that
     draws this glyph draws it masked, and Sigma-9 gives the pseudo no content
     at all — so a flat light fill is stated rather than a token branch, and
     this rule is NOT one of the two divergences: both builds state it. */
  #login-status::before {
    background-color: #c4cdd6 !important;
  }

  #search-top-box-input,
  #search-top-box input.text {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #3a4048 !important;
  }

  #search-top-box input.empty {
    color: #8b949e !important;
  }

  /* ============================================================
     SIDE BAR
     ============================================================ */

  /* Articles that ship their own theme paint #side-bar directly rather than
     through Black Highlighter's token, so the token rebind above cannot reach
     them. Sigma-9 leaves this element unpainted, so stating it costs nothing
     there. The border is drawn in currentColor by several of those themes. */
  #side-bar {
    background-color: #14181d !important;
    border-color: #2d333b !important;
  }

  #side-bar .side-block,
  #interwiki .side-block {
    background-color: #1c2128 !important;
    border-color: #7d3030 !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, .55);
  }

  /* The site tints two panels — keep those hues, at dark-surface lightness */
  #side-bar .side-block.media {
    background-color: #1e2133 !important;
  }

  #side-bar .side-block.resources {
    background-color: #17251d !important;
  }

  /* Black Highlighter puts the sidebar block heading's colour on a <p> INSIDE
     .heading, so the rule below — which paints .heading itself — is an
     inherited value the <p> overrides. Its token has to be rebound too. */
  #side-bar,
  #interwiki {
    --sideblock-heading-text-color: 224, 123, 131;
    --sidebar-links-text: 196, 205, 214;
  }

  #side-bar .heading,
  #interwiki .heading {
    color: #e07b83 !important;
    border-bottom-color: #7d3030 !important;
  }

  #side-bar .menu-item.inactive a {
    color: #7d858e !important;
  }

  #side-bar .menu-item .sub-text {
    color: #8b949e !important;
  }

  #side-bar .collapsible-block-unfolded-link {
    border-bottom-color: #7d3030 !important;
  }

  #side-bar .collapsible-block-unfolded-link .collapsible-block-link {
    color: #e07b83 !important;
  }

  #side-bar .collapsible-block-unfolded-link .collapsible-block-link:hover {
    color: #ff8f97 !important;
  }

  /* Mobile slide-out drawer */
  #side-bar .close-menu {
    background-color: rgba(0, 0, 0, .6);
  }

  /* Below 768px the drawer itself gets a dusty-rose fill from the site. */
  @media (max-width: 767px) {
    #side-bar {
      background-color: #0d1117 !important;
    }
  }

  /* ============================================================
     TABLES
     ============================================================ */

  /* No ink here: td would beat an author box's inherited colour the same way
     the page-content copy did. The cell text inherits; th states its own. */
  table.wiki-content-table td,
  table.wiki-content-table th {
    border-color: #2d333b !important;
  }

  table.wiki-content-table th {
    background-color: #22282f !important;
    color: #e6edf3 !important;
  }

  table.page-compare td,
  table.page-compare th,
  table.form.grid td,
  table.form.grid th,
  .gallery-item,
  table.page-history td.optionstd a {
    border-color: #2d333b !important;
  }

  .alternate:nth-child(2n) {
    background-color: rgba(255, 255, 255, .04) !important;
  }

  table.page-files .highlight {
    background-color: #22282f !important;
  }

  /* ============================================================
     CODE / TOC / NOTES / QUOTES
     ============================================================ */

  .code,
  #toc,
  .page-source,
  div.note {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  div.note-block {
    border-color: #7d3030 !important;
    background-color: #1a1f26 !important;
  }

  blockquote,
  div.blockquote {
    background-color: #1a1f26 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6;
  }

  .hl-default,
  .hl-code,
  .hl-brackets,
  .hl-identifier,
  .hl-main {
    color: #c9d1d9 !important;
  }

  .hl-comment {
    color: #8b949e !important;
  }

  .hl-quotes,
  .hl-string {
    color: #a5d6ff !important;
  }

  .hl-reserved {
    color: #ff7b72 !important;
  }

  .hl-var {
    color: #79c0ff !important;
  }

  .hl-inlinetags {
    color: #d2a8ff !important;
  }

  .hl-gutter {
    background-color: #22282f !important;
    color: #8b949e !important;
  }

  /* Footnote / bibliography rails. The footer is a filled panel under Black
     Highlighter and under the article themes derived from it, and those themes
     name its fill directly instead of through the token, so it is stated here
     rather than inherited. */
  .footnotes-footer,
  .bibitems,
  .footnote-footer,
  .footnote .f-content,
  .reference .r-content {
    border-color: #2d333b !important;
    color: #c4cdd6;
  }

  #page-content .footnotes-footer {
    background-color: #1a1f26 !important;
  }

  /* The "Footnotes" tab. Article themes state its ink near-black for their light
     panel and keep it when they repaint the tab in their accent, so the words
     vanish on the dark panel. Only the ink is taken — the accent fill is theirs. */
  #page-content .footnotes-footer .title {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* Every skin puts the back-reference digit in the anchor's own text, and Black
     Highlighter draws a SECOND copy from a ::before counter — it hides its own
     anchor to compensate, but the article-link rule above beats that and both
     print. Emptying the counter leaves exactly one digit on either skin. Hiding
     the anchor instead is not an option: Sigma-9 has no ::before to fall back on
     and the number disappears entirely. */
  #main-content #page-content .footnotes-footer a[href*="javascript"]::before {
    content: none !important;
  }

  /* The inline footnote popup. It is white-on-transparent and only
     `visibility: hidden` until hovered, so a load-time surface scan sees a
     white box that never moves; it is the article ink that has to be readable
     inside it. */
  #page-content .fncon {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  div.wiki-note,
  .hovertip {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
    box-shadow: 0 4px 14px rgba(0, 0, 0, .6);
  }

  /* Wikidot builds these cards in a container hung off the body, so every
     link rule scoped to #page-content stops short of them and an article theme
     that reaches links from a class chain keeps its light-page accent inside.
     The id is what outweighs that chain; an author's inline colour still wins. */
  #odialog-hovertips a {
    color: var(--scp-link);
  }

  #odialog-hovertips a:hover {
    color: var(--scp-link-hover);
  }

  .keycap {
    background-color: #22282f !important;
    border-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  /* ============================================================
     ARTICLE FURNITURE
     ============================================================ */

  .scp-image-block {
    border-color: #3a4048 !important;
    box-shadow: 0 1px 6px rgba(0, 0, 0, .5);
  }

  /* Sigma-9 draws only the caption's top rule; the article themes frame all four
     sides in their paper colour, which is a 4px white band on a dark page. Every
     side is stated — the three Sigma-9 leaves at zero width cost nothing. */
  .scp-image-block .scp-image-caption {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  /* The author-info rail's open panel. Article themes frame it in a near-white
     hairline pitched for their light page, which is the whole outline of the
     panel on a dark one. It exists only once the byline bar is expanded, so no
     load-time scan reaches it. */
  #page-content .info-container .collapsible-block-unfolded {
    border-color: #2d333b !important;
  }

  /* The ACS bar's diamond plate. It is drawn from whichever end of the article
     theme's own paper/ink pair suits its light page, so it lands as a glaring
     white slab on some themes and an invisible black one on others; an elevated
     grey keeps it a separator on every one. */
  #page-content .anom-bar .diamond-part::before {
    background-color: #2d333b !important;
  }

  /* The diamond's own hotspot: the ACS component stretches an anchor over the
     whole graphic and paints it `color: transparent` so only the artwork shows.
     That is one class, which the two-id article-link rule outweighs — the label
     then prints in crimson across the diamond and its underline draws a stray
     rule under it (the border takes currentColor). */
  #main-content #page-content .danger-diamond a,
  #main-content #page-content .danger-diamond a:visited,
  #main-content #page-content .danger-diamond a:hover {
    color: transparent !important;
    border-color: transparent !important;
  }

  div.sexy-box {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  div.sexy-box div.image-container img {
    border-color: #3a4048 !important;
  }

  .content-panel {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, .5);
  }

  .content-panel.standalone {
    background-color: #1a1f26 !important;
  }

  .content-panel .panel-body {
    background-color: #1c2128 !important;
    background-image: none !important;
    color: #c4cdd6;
  }

  .content-panel .panel-heading {
    color: #f0f0f0;
  }

  .content-panel .panel-footer {
    color: #d8d4c8;
  }

  .content-panel .content-toc {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    box-shadow: inset 1px 2px 6px rgba(0, 0, 0, .4);
  }

  div#u-adult-warning {
    background-color: #1c2128 !important;
    border-color: #4a5058 !important;
    color: #c4cdd6 !important;
  }

  div#u-adult-warning > div#u-adult-header {
    color: #e05f6b !important;
  }

  /* The gate's two actions are drawn in the site's near-black crimson, which the
     bare `a` rule cannot outweigh; on the dark panel they land at 2.4:1. */
  div#u-adult-warning .choice a {
    color: #e8626e !important;
  }

  div#u-adult-warning .choice a:hover {
    color: #ff8f97 !important;
  }

  .unflad-user-abusive,
  .unflag-user-abusive {
    color: #e08a8a !important;
    border-color: #4a5058 !important;
  }

  .flag-user-abusive,
  .unflag-user-ok {
    color: #9aa4ae !important;
    border-color: #3a4048 !important;
  }

  .flag-user-ok {
    color: #3fb950 !important;
    border-color: #3a4048 !important;
  }

  /* Wikidot tag pill */
  .tags {
    background-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  .tags::before {
    border-right-color: #3a4048 !important;
  }

  .tags::after {
    background-color: #c4cdd6 !important;
    box-shadow: -1px -1px 2px #14181d !important;
  }

  /* Sigma-9 draws the rule above the tag list on the inner span; article themes
     move it to the container and keep their light hex there. */
  #main-content .page-tags {
    border-top-color: #2d333b !important;
  }

  /* Sigma-9's own copy of that rule lives here, at 1px. The themes that moved it
     to the container leave this span an 8px TRANSPARENT spacer instead, which the
     colour alone fills as a slab across the page, so the width is clamped to the
     hairline. Themes that draw no rule at either place are untouched: a width
     cannot revive a `border-top-style: none`. */
  #main-content .page-tags span {
    border-top-color: #2d333b !important;
    border-top-width: 1px !important;
  }

  /* Tag list and the prev/next wikiwalk rail are furniture, not author prose,
     so their link colour is pinned against article themes that darken it.
     The paper has to come with it: a theme that fills each tag with a mid-grey
     chip states a knocked-out near-white ink to sit on it (/scp-8007 pairs
     #454545 with #f2f2f2), and taking only the ink leaves crimson on grey at
     2.9:1. Clearing the fill puts the pinned ink back on the page, where it
     measures 5.4:1; Sigma-9 never fills these, so it is unchanged. */
  #main-content .page-tags span a,
  #page-content .footer-wikiwalk-nav a {
    background-color: transparent !important;
    color: #e8626e !important;
  }

  /* That chip's left point is a CSS triangle drawn in the same fill, so it has
     to go with it or a stray grey arrow is left in front of every tag. Sigma-9
     gives this pseudo no border at all, so the rule costs nothing there. */
  #main-content .page-tags span a::before {
    border-color: transparent !important;
  }

  #main-content .page-tags span a:hover,
  #page-content .footer-wikiwalk-nav a:hover {
    color: #ff8f97 !important;
  }

  /* Wikidot writes the tag cloud's frequency gradient as inline per-tag
     colours, and the whole range — periwinkle through crimson — falls below
     AA on a dark page. Font size encodes the same frequency, so the tags take
     the site link colour and the size keeps the signal. */
  .pages-tag-cloud-box a.tag {
    color: #e8626e !important;
  }

  .pages-tag-cloud-box a.tag:hover {
    color: #ff8f97 !important;
  }

  .pages-tag-cloud-box a.tag.active {
    color: #ffb3b8 !important;
  }

  /* The guide family's navigation rail (/system:join, /guide-for-newcomers,
     /faq all ship the same [[module CSS]]) tints itself with
     rgba(191, 191, 191, .28) — a veil that reads as a faint grey over white
     paper and as a mid grey (#484c51) over a dark one, dropping the crimson
     links on it to 2.6:1. A dark plate puts them back to 4.9:1.
     Two ids are not needed and would be wrong: the page's own rule is a bare
     class, so this outranks it on specificity alone and an author who states a
     real colour still wins. */
  #page-content .navbox {
    background-color: #1a1f26;
  }

  /* ============================================================
     AUTHOR-WRITTEN INLINE COLOURS

     Wiki syntax like ##blue|text## emits a literal inline `color:`. The dark
     end of that palette is unreadable on a dark page, so lift the common
     names and hexes to the same hue at a legible lightness. Scoped to inline
     elements, where a `background-color:` collision effectively never occurs.
     ============================================================ */

  #page-content span[style*="color:black"],
  #page-content span[style*="color: black"],
  #page-content span[style*="color:#000000"],
  #page-content span[style*="color: #000000"],
  #page-content a[style*="color:black"],
  #page-content a[style*="color: black"],
  #page-content strong[style*="color:black"],
  #page-content strong[style*="color: black"],
  #page-content em[style*="color:black"],
  #page-content em[style*="color: black"] {
    color: var(--scp-lift-black) !important;
  }

  #page-content span[style*="color:blue"],
  #page-content span[style*="color: blue"],
  #page-content span[style*="color:navy"],
  #page-content span[style*="color: navy"],
  #page-content span[style*="color:steelblue"],
  #page-content span[style*="color: steelblue"],
  #page-content span[style*="color:#0000ff"],
  #page-content span[style*="color: #0000ff"],
  #page-content span[style*="color:#4682b4"],
  #page-content span[style*="color: #4682b4"],
  #page-content a[style*="color:blue"],
  #page-content a[style*="color: blue"],
  #page-content a[style*="color:navy"],
  #page-content a[style*="color: navy"],
  #page-content a[style*="color:steelblue"],
  #page-content a[style*="color: steelblue"],
  #page-content strong[style*="color:blue"],
  #page-content strong[style*="color: blue"],
  #page-content strong[style*="color:steelblue"],
  #page-content strong[style*="color: steelblue"],
  #page-content em[style*="color:blue"],
  #page-content em[style*="color: blue"],
  #page-content em[style*="color:steelblue"],
  #page-content em[style*="color: steelblue"] {
    color: var(--scp-lift-blue) !important;
  }

  #page-content span[style*="color:green"],
  #page-content span[style*="color: green"],
  #page-content span[style*="color:#008000"],
  #page-content span[style*="color: #008000"],
  #page-content a[style*="color:green"],
  #page-content a[style*="color: green"],
  #page-content strong[style*="color:green"],
  #page-content strong[style*="color: green"],
  #page-content em[style*="color:green"],
  #page-content em[style*="color: green"] {
    color: var(--scp-lift-green) !important;
  }

  #page-content span[style*="color:purple"],
  #page-content span[style*="color: purple"],
  #page-content span[style*="color:indigo"],
  #page-content span[style*="color: indigo"],
  #page-content span[style*="color:#800080"],
  #page-content span[style*="color: #800080"],
  #page-content a[style*="color:purple"],
  #page-content a[style*="color: purple"],
  #page-content strong[style*="color:purple"],
  #page-content strong[style*="color: purple"],
  #page-content em[style*="color:purple"],
  #page-content em[style*="color: purple"] {
    color: var(--scp-lift-purple) !important;
  }

  /* #990000 is the clearance-level red the standard "Level n/xxxx — Classified"
     header snippet ships with, so it turns up on a large share of articles and
     lands at 2.0:1 here. */
  #page-content span[style*="color:maroon"],
  #page-content span[style*="color: maroon"],
  #page-content span[style*="color:darkred"],
  #page-content span[style*="color: darkred"],
  #page-content span[style*="color:#800000"],
  #page-content span[style*="color: #800000"],
  #page-content span[style*="color:#990000"],
  #page-content span[style*="color: #990000"],
  #page-content a[style*="color:maroon"],
  #page-content a[style*="color: maroon"],
  #page-content a[style*="color:#990000"],
  #page-content a[style*="color: #990000"],
  #page-content strong[style*="color:maroon"],
  #page-content strong[style*="color: maroon"],
  #page-content strong[style*="color:#990000"],
  #page-content strong[style*="color: #990000"],
  #page-content em[style*="color:maroon"],
  #page-content em[style*="color: maroon"],
  #page-content em[style*="color:#990000"],
  #page-content em[style*="color: #990000"] {
    color: var(--scp-lift-maroon) !important;
  }

  /* Pure red lands at 4.46:1 — a hair under AA. Softened just enough to pass
     while staying unmistakably the same red. */
  #page-content span[style*="color:red"],
  #page-content span[style*="color: red"],
  #page-content span[style*="color:#ff0000"],
  #page-content span[style*="color: #ff0000"],
  #page-content a[style*="color:red"],
  #page-content a[style*="color: red"],
  #page-content strong[style*="color:red"],
  #page-content strong[style*="color: red"],
  #page-content em[style*="color:red"],
  #page-content em[style*="color: red"] {
    color: var(--scp-lift-red) !important;
  }

  #page-content span[style*="color:brown"],
  #page-content span[style*="color: brown"],
  #page-content span[style*="color:sienna"],
  #page-content span[style*="color: sienna"],
  #page-content span[style*="color:#a0522d"],
  #page-content span[style*="color: #a0522d"],
  #page-content a[style*="color:brown"],
  #page-content a[style*="color: brown"],
  #page-content a[style*="color:sienna"],
  #page-content a[style*="color: sienna"],
  #page-content strong[style*="color:brown"],
  #page-content strong[style*="color: brown"],
  #page-content strong[style*="color:sienna"],
  #page-content strong[style*="color: sienna"] {
    color: var(--scp-lift-brown) !important;
  }

  #page-content span[style*="color:teal"],
  #page-content span[style*="color: teal"],
  #page-content span[style*="color:#008080"],
  #page-content span[style*="color: #008080"],
  #page-content a[style*="color:teal"],
  #page-content a[style*="color: teal"],
  #page-content strong[style*="color:teal"],
  #page-content strong[style*="color: teal"] {
    color: var(--scp-lift-teal) !important;
  }

  /* Redacted / blackout spans keep working on dark */
  .bblock,
  .dblock {
    color: #000 !important;
    background-color: #000 !important;
  }

  .bblock:hover {
    color: #060 !important;
  }

  /* ============================================================
     RATING WIDGET
     ============================================================ */

  .page-rate-widget-box {
    box-shadow: 1px 1px 4px rgba(0, 0, 0, .6);
  }

  div.page-rate-widget-box .rate-points {
    background-color: #5a2f2f !important;
    border-color: #5a2f2f !important;
