  }

  .page-rate-widget-box .cancel a:hover {
    background-color: #7d4444 !important;
    color: #fff6f0 !important;
  }

  /* Articles with a credit module wrap the widget in a second maroon strip that
     carries the "i" button; it has to track .rate-points, which is darker than
     the maroon the site ships. */
  .rate-box-with-credit-button {
    background-color: #5a2f2f !important;
    border-color: #5a2f2f !important;
  }

  /* The site paints this button white precisely because it sits on the maroon;
     the page-wide link colour drops it to ~3:1 there. */
  .creditButton a {
    color: #f0e2e2 !important;

    /* only the left side is drawn — it is the widget's separator, and pinning
       it stops the other three inheriting the new text colour */
    border-color: #996666 !important;
  }

  .creditButton a:hover {
    color: #fff !important;
  }

  /* The credit panel itself, opened by that button. Its surface is a
     background-IMAGE — a grey title strip above a white body — so a
     background-color alone never reaches it. */
  #u-credit-view .modalbox {
    background-color: #1c2128 !important;
    background-image: linear-gradient(#22282f 51px, #1c2128 51px, #1c2128) !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  #u-credit-view .fader {
    background-color: rgba(0, 0, 0, .7) !important;
  }

  /* ============================================================
     YUI TABS
     ============================================================ */

  .yui-navset .yui-content,
  .yui-navset .yui-navset-top .yui-content {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    border-top-color: #7d3030 !important;
    color: #c4cdd6;
  }

  .yui-navset-left .yui-content {
    border-color: #2d333b !important;
    border-left-color: #7d3030 !important;
  }

  .yui-navset-bottom .yui-content,
  .yui-navset .yui-navset-bottom .yui-content {
    border-color: #2d333b !important;
    border-bottom-color: #7d3030 !important;
  }

  .yui-navset .yui-nav,
  .yui-navset .yui-navset-top .yui-nav {
    border-color: #7d3030 !important;
  }

  .yui-navset .yui-nav a,
  .yui-navset .yui-navset-top .yui-nav a {
    background-color: #22282f !important;
    background-image: none !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* Hub pages put the tab's label in this <em> and give it a near-black ink
     with a white halo on all four sides — a sticker cut for a light strip,
     which on a dark one prints hollow outlined letters. The label follows the
     anchor instead, so the selected tab's knocked-out white comes with it. */
  .yui-navset .yui-nav a em,
  .yui-navset .yui-navset-top .yui-nav a em {
    border-color: #2d333b !important;
    color: inherit !important;
    text-shadow: none !important;
  }

  /* The frame those hub pages draw around the whole tab widget. */
  #page-content .tab-box {
    border-color: #2d333b !important;
  }

  .yui-navset .yui-nav a:hover,
  .yui-navset .yui-nav a:focus {
    background-color: #33272a !important;
    background-image: none !important;
    color: #ff8f97 !important;
  }

  .yui-navset .yui-nav .selected a,
  .yui-navset .yui-nav .selected a:focus,
  .yui-navset .yui-nav .selected a:hover {
    background-color: #8a2f2f !important;
    background-image: none !important;
    color: #fff !important;
  }

  .yui-navset .yui-nav .selected a,
  .yui-navset .yui-nav .selected a em {
    border-color: #8a2f2f !important;
  }

  /* Some articles put the tab's label in a pseudo-element with a hardcoded
     black fill, which disappears once the tab strip goes dark. */
  .yui-navset .yui-nav a::before,
  .yui-navset .yui-nav a::after {
    color: inherit !important;
  }

  /* ============================================================
     FORMS / BUTTONS / DIALOGS
     ============================================================ */

  input.text,
  input[type="text"],
  input[type="search"],
  input[type="password"],
  input[type="email"],
  textarea,
  select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #3a4048 !important;
  }

  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1;
  }

  input.checkbox {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* Wikidot's `.btn*` classes are bare text links on ANCHORS here (the page-options
     bar, forum Reply/Fold/Options), so `a.btn` is deliberately absent. On an INPUT
     the same class is a real submit — the forum's "Update" filter button carries
     `.buttons.btn` and nothing else, so it needs `input.btn` to be reached.
     The masthead search submit carries `.button.btn` too and is the site's only
     `[name="search"]`, but it is not one of these buttons: Black Highlighter
     masks it to a magnifier and relies on its own `color: transparent` to keep
     the "Search" value from punching through the glyph, so a light ink stated
     here would print the word across the icon. That exclusion is the second
     deliberate divergence from the .user.css — it is what lets the mid-tone
     search fill above render a clean glyph, and the .user.css does not need it
     because the token it reads is near-white on every masked skin. */
  div.buttons input,
  input.button:not([name="search"]),
  input.btn:not([name="search"]),
  button,
  a.button {
    background-color: #262c33 !important;
    border-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  /* That button keeps the UA's `outset` bevel, which draws its own light/dark
     pair from the border colour and ignores the one set above. */
  input.btn:not([name="search"]) {
    border-style: solid !important;
  }

  div.buttons input:hover,
  input.button:not([name="search"]):hover,
  input.btn:not([name="search"]):hover,
  button:hover,
  a.button:hover {
    background-color: #333a42 !important;
    color: #fff !important;
  }

  .page-options-bottom a,
  a.btn.btn-default {
    color: #e8626e;
  }

  .page-options-bottom a:hover,
  a.btn.btn-default:hover {
    color: #ff8f97;
  }

  input.button.disabled,
  div.buttons input.disabled,
  input.button.disabled:hover,
  div.buttons input.disabled:hover {
    background-color: #1a1f26 !important;
    color: #6b737c !important;
  }

  table.form td div.sub,
