  /* ============================================================
     CONSENT MANAGER (NitroPay)

     A white modal on every first visit, plus the privacy dashboard behind
     "Advanced Settings". Recoloured only — the banner's emphasis hierarchy is
     left as the site ships it, so neither choice gains or loses prominence.
     The banner and the dashboard hang off two SEPARATE roots (#ncmp__tool and
     #ncmp__modal), hence the scoping by the vendor's own class prefix.
     ============================================================ */

  .ncmp__banner,
  .ncmp__modal {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  /* Only the page scrim. .ncmp__vendor-shadow covers the whole dashboard and is
     transparent until the vendor drawer opens — painting it dims the panel. */
  .ncmp__shadow {
    background-color: rgba(0, 0, 0, .7) !important;
  }

  .ncmp__banner h1,
  .ncmp__banner h2,
  .ncmp__banner h3,
  .ncmp__banner strong,
  .ncmp__modal h1,
  .ncmp__modal h2,
  .ncmp__modal h3,
  .ncmp__modal strong,
  .ncmp__banner-emphasis,
  .ncmp__section-title {
    background-color: transparent !important;
    color: #e6edf3 !important;
  }

  .ncmp__banner p,
  .ncmp__modal p,
  .ncmp__section-details,
  .ncmp__list-info,
  .ncmp__vendor-consent,
  .ncmp__toggle-on,
  .ncmp__toggle-off,
  .ncmp__toggle-purposes-on,
  .ncmp__description-legal,
  .ncmp__description-legal span,
  .ncmp__section-body li,
  .ncmp__section-body span {
    color: #c4cdd6 !important;
  }

