  .ncmp__branding-version a {
    border-color: #7d3030 !important;
  }

  .ncmp__btn {
    background-color: #8a2f2f !important;
    border-color: #8a2f2f !important;
    color: #fff !important;
  }

  .ncmp__btn:hover {
    background-color: #a03636 !important;
    color: #fff !important;
  }

  .ncmp__btn.ncmp__btn-border,
  .ncmp__btn.ncmp__btn-danger {
    background-color: transparent !important;
    border-color: #c98a8a !important;
    color: #e8949a !important;
  }

  .ncmp__btn.ncmp__btn-border:hover,
  .ncmp__btn.ncmp__btn-danger:hover {
    background-color: #33272a !important;
    color: #ffd5d8 !important;
