  /* ============================================================
     HOME PAGE — the site's own custom front-page theme
     ============================================================ */

  #page-content {
    --dark: #e6edf3;
    --light: #1c2128;
    --box-accent: #8a4444;
    --active: #a03636;
    --link-color: #e8626e;
    --link-bg: #e8626e1f;
    --attention: #2a2418;
