    --link-bg: #6fbc8a1f;
  }

  /* Text that must stay light because it sits on an accent/photo fill */
  #page-content .box .title,
  #page-content .caption,
  #page-content .box .title p {
    color: #f2f2f2 !important;
  }

  /* Slide-in quote panel: natively dark-on-light, kept dark-on-dark */
  #page-content .bq {
    background-color: #0d1117 !important;
    color: #c4cdd6 !important;
  }

  #page-content .dropdown > a::after {
    background-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  #page-content .box,
  #page-content .dropdown-content,
  #page-content .art-slide {
    background-color: #1c2128 !important;
  }

  #page-content .feature1box:hover,
  #page-content .feature2box:hover,
  #page-content .feature3box:hover,
  #page-content .feature4box:hover,
  #page-content .feature1box:focus-within,
  #page-content .feature2box:focus-within,
  #page-content .feature3box:focus-within,
  #page-content .feature4box:focus-within {
    color: #e6edf3 !important;
  }

  /* The hover sweep is a ::before that inverts whatever is behind it — on the
     site's white card that reads as a dark wipe, on a dark card it flashes the
     whole tile near-white. The wipe becomes a crimson wash instead, and the
     ::after's screen blend (which lightened it further) is emptied out. The
     0 -> 100% width animation is untouched. */
  #page-content .feature1box::before,
  #page-content .feature2box::before,
  #page-content .feature3box::before,
  #page-content .feature4box::before {
    backdrop-filter: none !important;
    background-color: rgba(224, 95, 107, .13) !important;
  }

  #page-content .feature1box::after,
  #page-content .feature2box::after,
  #page-content .feature3box::after,
  #page-content .feature4box::after {
    background-color: transparent !important;
  }

  #page-content .site-news {
    --ink: #dfe3f0;
    --paper: #1a1f26;

    background-color: #171b28 !important;
    color: #dfe3f0 !important;
  }

  /* Section-heading rules and the news bracket are hairlines drawn in the
     body ink; at full ink they glare on a dark page. */
  #page-content .low-weight h2 > span,
  #page-content .section-head h2::after,
  #page-content .low-weight h2::after {
    border-color: #8b949e !important;
  }

  #page-content .site-news .news-snippet {
    border-color: #737ea6 !important;
  }

  #page-content .site-news .news-snippet::before,
  #page-content .site-news .news-snippet::after {
