  }

  #page-content .placard::before,
  #page-content .placard::after {
    background: radial-gradient(at 50% 0, rgba(0, 0, 0, .45), rgba(0, 0, 0, 0) 65%) !important;
  }

  /* The event banner is author-drawn art: a parchment file panel painted by
     .event-opener::before, carrying the author's own near-black ink. The page
     ink and the --dark/--light remap above would leave that text a ghost on the
     paper, so the banner opts back out of both. */
  #page-content .event-banner {
    --dark: #333;
    --light: #fff;
    --box-accent: #823f3f;
    --active: #700;
    --link-color: #b01;
    --link-bg: #c0696014;
  }

  #page-content .event-banner,
  #page-content .event-banner p,
  #page-content .event-banner li,
  #page-content .event-banner dd,
  #page-content .event-banner dt,
  #page-content .event-banner td {
    color: #1b1815 !important;
  }

  /* The front page resets these to bare strips inside its category cards. */
  #page-content .core-categories > div > blockquote {
    background-color: transparent !important;
    border-color: transparent !important;
  }

  /* The seal's two inner rings are inset shadows, and the outer one is the paper
     colour: on the site's white card it is the gap that sets the blue ring off
     from the black frame, and on a dark one it is a white halo. It follows the
     card. The blue ring is the brand and the widths are the site's. */
  #page-content .INT-box {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    box-shadow: inset 0 0 0 .175rem #1a1f26, inset 0 0 0 .675rem #4b92db !important;
  }

  #page-content .INT-box > .collapsible-block .collapsible-block-link {
    background-color: #1a1f26 !important;
    color: #6fa8e0 !important;
  }

  #page-content .INT-box > .collapsible-block .collapsible-block-content {
    border-color: #3a648c !important;
  }

  #page-content .library {
    border-color: rgba(0, 0, 0, .65) !important;
  }

  /* ============================================================
     NEWSPAPER THEME — the Site News family
     ============================================================ */

  /* One token paints every panel this theme owns: inline code, the disclaimer
     placard, the rating strip, blockquotes, image captions, table headers, the
     section-header rules and the divider ornaments. Its two uses as knocked-out
     text — the selected tab's label and the unfolded collapsible's link — sit on
     the theme's accent and are already pinned light by the rules above. */
  :root {
    --primaryBackgroundColor: #1a1f26;
  }

  /* The panels it fills with a literal cream instead of that token. */
  #page-content .f-con,
  #page-content .tocbox .toc-u {
    background-color: #1a1f26 !important;
  }

  /* It fills the open state of a collapsible with its accent and knocks the
     label out of that fill, which the article-link colour takes back — leaving
     crimson on red. Clearing the fill leaves the accent ring the theme draws
     around the same element, so the open state keeps its cue; no other skin
     fills this element at all, so the reset is inert on them. */
  #page-content .collapsible-block-unfolded-link {
    background-color: transparent !important;
  }

  /* Its sidebar links are reached from a class chain the site-wide link rule
     cannot outweigh, at an accent red pitched for a cream rail. */
  #side-bar div.menu-item a,
  #interwiki div.menu-item a {
    color: var(--scp-link) !important;
  }

  #side-bar div.menu-item a:hover,
  #interwiki div.menu-item a:hover {
    color: var(--scp-link-hover) !important;
  }

  /* ============================================================
     SITE SEARCH (the Crom widget's host page)
     ============================================================ */

  #u-framewrapper {
    background-color: #14181d !important;
  }

  /* Shimmer placeholder shown until the search widget loads */
  #u-loading {
    background-image: linear-gradient(#14181d 10%, #1c2128 50%, #14181d 90%) !important;
  }

  .cromplug,
  .cromwalk,
  .cromplug p,
  .cromwalk p {
    background-color: #241b1e !important;
    border-color: #8a5f68 !important;
    color: #d8929c !important;
  }

  .cromplug p,
  .cromwalk p {
    background-color: transparent !important;
  }

  /* Crom's crow is a black silhouette drawn for the light pink box; on dark it
     is an invisible smudge, so drop it and keep the labelled link. */
  .cromplug {
    background-image: none !important;
  }

  .cromplug a,
  .cromwalk a {
    color: #e8626e !important;
  }

  /* ============================================================
     INTERWIKI FRAME (other-languages box)
     ============================================================ */

  #interwiki body,
  body#interwiki {
    background-color: transparent !important;
  }

  /* The frame ELEMENT's own fill, which the article themes set from their
     resources-block green (/scp-8007 leaves it #e8f7ea). The frame's document
     normally paints over it, so it only shows while that document loads — or
     for good, when a blocker stops the third-party frame from loading at all. */
  iframe.scpnet-interwiki-frame {
    background-color: #14181d !important;
  }

  #interwiki .menu-item a {
    color: #e8626e !important;
  }
}

@-moz-document url-prefix("https://crom.avn.sh/embed/") {
:root {
    color-scheme: dark;

    /* The widget is Tailwind — remapping its palette tokens reaches every
       utility at once, and beats the utility layer's cascade. */
    --color-white: #171c22;
    --color-black: #0d1117;
    --color-gray-100: #262c33;
    --color-gray-200: #2d333b;
    --color-gray-300: #3a4048;
    --color-gray-400: #6b737c;
    --color-gray-500: #8b949e;
    --color-gray-600: #c4cdd6;
    --color-gray-700: #d0d8e0;
    --color-gray-800: #e0e7ee;
    --color-gray-900: #e6edf3;

    /* Crom's rose accent scale, re-pitched for a dark surface */
    --color-blush-50: #241b1e;
    --color-blush-100: #2b2124;
    --color-blush-200: #8a5f68;
    --color-blush-300: #a8737d;
    --color-blush-400: #c48792;
    --color-blush-500: #d8929c;
    --color-blush-600: #e2757f;
    --color-blush-700: #e8626e;
    --color-blush-800: #ef7d87;
    --color-blush-900: #f5a0a8;
  }

  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1;
  }
}
